package com.brightloop.invoice;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;import java.util.Optional;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;
public interface InvoiceRepository extends JpaRepository<Invoice,Long>{Optional<Invoice> findBySubscriptionIdAndBillingPeriodStart(Long id,LocalDate start);List<Invoice> findByCustomerId(Long customerId);List<Invoice> findByCustomerEmailIgnoreCase(String email);List<Invoice> findByOutstandingGreaterThanAndDueDateBefore(BigDecimal amount,LocalDate date);List<Invoice> findByOutstandingGreaterThanAndDueDateBetween(BigDecimal amount,LocalDate from,LocalDate to);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select i from Invoice i where i.id=:id") Optional<Invoice> findForUpdate(@Param("id") Long id);@Query("select coalesce(sum(i.outstanding),0) from Invoice i where i.outstanding>0") BigDecimal outstandingTotal();long countByOutstandingGreaterThanAndDueDateBefore(BigDecimal amount,LocalDate dueDate);}
